/** A located statement planted in a location: its head, then the wrapper around its body. */
function locatedText(row: LocatedRow, location: LocationRow): string {
  const body = row.body
    .split("\n")
    .filter(line => line !== "")
    .map(line => `${" ".repeat(location.indent)}${line}\n`)
    .join("");
  return `${row.head}${location.prefix}${body}${location.suffix}`;
}
